import{_ as a,a0 as o,w as u,s as p,I as s,x as i,a1 as e,A as n,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"三種 Linux 下的 SSH 圖形界面工具 | LCTT x X-CMD","titleTemplate":false,"description":"三種 Linux 下的 SSH 圖形界面工具 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三種 Linux 下的 SSH 圖形界面工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三種 Linux 下的 SSH 圖形界面工具 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20181123 Three SSH GUI Tools for Linux","title":"三種 Linux 下的 SSH 圖形界面工具","tag":"202101","desc":""},"relativePath":"202101/20181123 Three SSH GUI Tools for Linux.md","filePath":"[post].md"}'),d={name:"202101/20181123 Three SSH GUI Tools for Linux.md"};function S(g,t,m,T,h,b){const l=o("Link");return u(),p("div",null,[t[24]||(t[24]=s("h1",{id:"三種-linux-下的-ssh-圖形界面工具",tabindex:"-1"},[i("三種 Linux 下的 SSH 圖形界面工具 "),s("a",{class:"header-anchor",href:"#三種-linux-下的-ssh-圖形界面工具","aria-label":"Permalink to “三種 Linux 下的 SSH 圖形界面工具”"},"​")],-1)),t[25]||(t[25]=s("p",null,[s("img",{src:"https://lcom.static.linuxfound.org/sites/lcom/files/ssh.jpg",alt:""})],-1)),t[26]||(t[26]=s("p",null,"在你作為 Linux 系統管理員的職業生涯中，你可以使用 Secure Shell（SSH）遠程訪問 Linux 服務器或桌面系統。很有可能，你已經使用過了。在某些情況下，你會通過 SSH 一次性登錄多個 Linux 服務器。實際上，SSH 很可能是 Linux 工具箱中最常用的工具之一。因此，你會希望操作儘可能高效。對於許多系統管理員來説，沒有什麼比命令列更有效的了。但是，有些用户確實更喜歡 GUI 工具，尤其是從一台桌面台式機遠程連接到服務器上工作時。",-1)),t[27]||(t[27]=s("p",null,"如果你碰巧喜歡 GUI 工具，那麼你肯定想了解一下 Linux 上的一些出色的 SSH 圖形界面工具。將其與獨特的終端窗口相結合，可以從同一窗口遠程訪問多台計算機，你便擁有了高效工作所需的一切。讓我們看以下這三個工具，找出其中一個（或多個）是否完全適合你的需求。",-1)),s("p",null,[t[1]||(t[1]=i("我將在 ",-1)),e(l,{href:"https://elementary.io/"},{default:n(()=>[...t[0]||(t[0]=[i("Elementary OS",-1)])]),_:1}),t[2]||(t[2]=i(" 上演示這些工具，但是大多數流行的發行版都可以使用它們。",-1))]),t[28]||(t[28]=s("h3",{id:"putty",tabindex:"-1"},[i("PuTTY "),s("a",{class:"header-anchor",href:"#putty","aria-label":"Permalink to “PuTTY”"},"​")],-1)),s("p",null,[t[4]||(t[4]=i("只要是久經沙場的人都知道 ",-1)),e(l,{href:"https://www.chiark.greenend.org.uk/~sgtatham/putty/latest.html"},{default:n(()=>[...t[3]||(t[3]=[i("PuTTY",-1)])]),_:1}),t[5]||(t[5]=i("。 實際上，PuTTY 是從 Windows 環境通過 SSH 連接到 Linux 服務器的事實標準工具。但是 PuTTY 不僅適用於 Windows。實際上，從其標準存儲庫中，PuTTY 也可以安裝到 Linux 上。 PuTTY 的功能列表包括：",-1))]),t[29]||(t[29]=r('<ul><li>保存會話</li><li>通過 IP 地址或主機名鏈接</li><li>定義備用 SSH 端口</li><li>鏈接類型定義</li><li>日誌記錄</li><li>鍵盤、響鈴、外觀、連接等選項</li><li>本地和遠程隧道配置</li><li>支持代理</li><li>支持X11 隧道</li></ul><p>PuTTY GUI 主要是一種保存 SSH 會話的方式，因此，你可以更輕鬆地管理那些你需要不斷遠程登錄、登出的各種 Linux 服務器和桌面台式機。從 PuTTY 連接到 Linux 服務器後，你將擁有一個可以運行的終端窗口。此時，你可能會問自己，為什麼不只在終端窗口中工作？對於某些人來説，保存會話的便捷性確實使 PuTTY 值得使用。</p><p>在 Linux 上安裝 PuTTY 很簡單。例如，你可以在基於 Debian 的發行版上執行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install -y putty</span></span></code></pre></div><p>安裝後，你可以從桌面菜單運行 PuTTY GUI 或執行命令 <code>putty</code>。在“<ruby>PuTTY 配置<rt>PuTTY Configuration</rt></ruby>” 窗口（圖 1）中，在 “<ruby>主機名（或 IP 地址）<rt>HostName (or IP address)</rt></ruby>”位置鍵入主機名或 IP 地址，配置<ruby>端口<rt>Port</rt></ruby>”（如果不是默認值 22），從“<ruby>連接類型<rt>Connection type</rt></ruby>”中選擇 “SSH” ，然後單擊“<ruby>打開<rt>Open</rt></ruby>”。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/ssh_guis_1.jpg" alt="PuTTY Connection" title="PuTTY Connection"></p><p><em>圖 1：PuTTY 連接配置窗口。</em></p><p>建立連接後，系統將提示你輸入遠程服務器上的用户憑據（圖 2）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/ssh_guis_2.jpg" alt="log in" title="log in"></p><p><em>圖 2：使用 PuTTY 登錄到遠程服務器。</em></p><p>要保存會話（以便不必總是鍵入遠程服務器信息），填寫 IP 地址（或主機名），配置端口和連接類型，然後（在單擊 “<ruby>打開<rt>Open</rt></ruby>” 之前），在 “<ruby>保存會話<rt>Saved Sessions</rt></ruby>” 頂部文本區域中鍵入鏈接的名稱，然後單擊 “<ruby>保存<rt>Save</rt></ruby>”。 這樣將保存此會話的配置。若要連接到已保存的會話，請從 “<ruby>已保存的會話<rt>Saved Sessions</rt></ruby>” 窗口中選擇它，單擊 “<ruby>加載<rt>Load</rt></ruby>”，然後單擊 “<ruby>打開<rt>Open</rt></ruby>”。 然後，系統將提示你輸入遠程服務器上的遠程憑據登錄遠程服務器。</p><h3 id="easyssh" tabindex="-1">EasySSH <a class="header-anchor" href="#easyssh" aria-label="Permalink to “EasySSH”">​</a></h3>',12)),s("p",null,[t[7]||(t[7]=i("儘管 ",-1)),e(l,{href:"https://github.com/muriloventuroso/easyssh"},{default:n(()=>[...t[6]||(t[6]=[i("EasySSH",-1)])]),_:1}),t[8]||(t[8]=i(" 沒有提供 PuTTY 中提供的大量配置選項，但是（顧名思義）它非常易於使用。 EasySSH 的最佳功能之一是提供標籤式界面，因此你可以打開多個 SSH 連接並在它們之間快速切換。 EasySSH 的功能包括：",-1))]),t[30]||(t[30]=r(`<ul><li>分組（你可以將選項卡分組以獲得更高效的體驗）。</li><li>保存用户名/密碼。</li><li>外觀選項。</li><li>支持本地和遠程隧道。</li></ul><p>在 Linux 桌面上安裝 EasySSH 很簡單，因為可以通過 flatpak 安裝該應用程序（這意味着你必須在系統上安裝 Flatpak ）。 安裝 flatpak 後，使用以下命令添加 EasySSH ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo flatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakrepo</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sudo flatpak install flathub com.github.muriloventuroso.easyssh</span></span></code></pre></div><p>使用以下命令運行 EasySSH ：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak run com.github.muriloventuroso.easyssh</span></span></code></pre></div><p>你可以在其中單擊左上角的 “+” 按鈕打開 EasySSH 應用程序。 在出現的窗口（圖 3）中，根據需要配置 SSH 連接。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/ssh_guis_3.jpg" alt="Adding a connection" title="Adding a connection"></p><p><em>圖 3：在 EasySSH 中添加連接很簡單。</em></p><p>添加連接後，它將顯示在主窗口的左側導航中（圖 4）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/ssh_guis_4.jpg" alt="EasySSH" title="EasySSH"></p><p><em>圖 4：EasySSH 主窗口。</em></p><p>要在 EasySSH 中連接到遠程服務器，請從左側導航中選擇它，然後單擊 “<ruby>連接<rt>Connect</rt></ruby>” 按鈕（圖 5）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/ssh_guis_5.jpg" alt="Connecting" title="Connecting"></p><p><em>圖 5：使用 EasySSH 連接到遠程服務器。</em></p><p>EasySSH 的一個注意事項是你必須在連接配置中保存用户名和密碼（否則連接將失敗）。這意味着有權訪問運行 EasySSH 的桌面的任何人都可以在不知道密碼的情況下遠程訪問你的服務器。因此，你必須始終記得在外出時鎖定桌面屏幕（並確保使用強密碼）。你最不希望的就是避免服務器受到不必要的登錄攻擊。</p><h3 id="terminator" tabindex="-1">Terminator <a class="header-anchor" href="#terminator" aria-label="Permalink to “Terminator”">​</a></h3><p>Terminator 實際上不是 SSH GUI。相反，Terminator 的功能是作為一個單一窗口，使你可以一次運行多個終端（甚至一組終端）。實際上，你可以打開 Terminator，將窗口垂直和水平拆分（直到擁有所需的所有終端），然後通過標準 SSH 命令連接到所有遠程 Linux 服務器（圖 6）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/ssh_guis_6.jpg" alt="Terminator" title="Terminator"></p><p><em>圖 6：Terminator 分為三個不同的窗口，每個窗口都連接到不同的 Linux 服務器。</em></p><p>要安裝 Terminator，請執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install -y terminator</span></span></code></pre></div><p>安裝後，從桌面菜單或用命令 <code>terminator</code> 打開該工具。打開窗口後，你可以在 Terminator 內部右鍵單擊，然後選擇 “<ruby>水平分割<rt>Split Horizontally</rt></ruby>” 或 “<ruby>垂直分割<rt>Split Vertically</rt></ruby>”。繼續拆分終端，直到你打開所需的終端為止，然後開始遠程管理這些服務器。使用 Terminator 的注意事項是它不是標準的 SSH GUI 工具，因為它不會保存你的會話或使你可以快速訪問這些服務器。換句話説，你將始終必須手動登錄到遠程 Linux 服務器。但是，能夠並行查看遠程 Secure Shell 會話確實使管理多個遠程計算機變得容易得多。</p><h3 id="少而精的選擇" tabindex="-1">少而精的選擇 <a class="header-anchor" href="#少而精的選擇" aria-label="Permalink to “少而精的選擇”">​</a></h3><p>Linux 沒有多少可用的 SSH GUI 工具。為什麼呢？因為大多數管理員更喜歡簡單地打開終端窗口，並使用標準命令列工具來遠程訪問服務器。但是，如果需要 GUI 工具，則有兩個可靠的選擇，和一個使登錄多台計算機稍微容易一些的終端。儘管對於那些尋找 SSH GUI 工具的人來説只有少數選擇，但是可用的那些肯定值得你花時間，根據需要嘗試其中之一。</p><hr>`,25)),s("p",null,[t[10]||(t[10]=i("via: ",-1)),e(l,{href:"https://www.linux.com/blog/learn/intro-to-linux/2018/11/three-ssh-guis-linux"},{default:n(()=>[...t[9]||(t[9]=[i("https://www.linux.com/blog/learn/intro-to-linux/2018/11/three-ssh-guis-linux",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=i("作者：",-1)),e(l,{href:"https://www.linux.com/users/jlwallen"},{default:n(()=>[...t[11]||(t[11]=[i("Jack Wallen",-1)])]),_:1}),t[16]||(t[16]=i(" 選題：",-1)),e(l,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[12]||(t[12]=[i("lujun9972",-1)])]),_:1}),t[17]||(t[17]=i(" 譯者：",-1)),e(l,{href:"https://github.com/stevenzdg988"},{default:n(()=>[...t[13]||(t[13]=[i("stevenzdg988",-1)])]),_:1}),t[18]||(t[18]=i(" 校對：",-1)),e(l,{href:"https://github.com/wxy"},{default:n(()=>[...t[14]||(t[14]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[21]||(t[21]=i("本文由 ",-1)),e(l,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[19]||(t[19]=[i("LCTT",-1)])]),_:1}),t[22]||(t[22]=i(" 原創編譯，",-1)),e(l,{href:"https://linux.cn/"},{default:n(()=>[...t[20]||(t[20]=[i("Linux中國",-1)])]),_:1}),t[23]||(t[23]=i(" 榮譽推出",-1))])])}const k=a(d,[["render",S]]);export{x as __pageData,k as default};
